tool.command:
@SHELL_OPTIONS@
## create symlinks to input datasets ln -s '$constaxonomy' con.taxonomy && #if $otu.is_of_type("mothur.shared"): ln -s '$otu' input.shared && #elif $otu.is_of_type("mothur.list"): ln -s '$otu' input.list && #else: ln -s '$otu' input.relabund && #end if
echo 'merge.otus( #if $label: label=${ str($label).replace(",","-") }, #end if #if $taxlevel: taxlevel=$taxlevel, #end if #if $otu.is_of_type("mothur.shared"): shared=input.shared, #elif $otu.is_of_type("mothur.list"): list=input.list, #else: relabund=input.relabund, #end if constaxonomy=con.taxonomy )' | sed 's/ //g; s/,)$/)/' ## mothur trips over whitespace; a trailing comma segfaults mothur >1.42 | mothur | tee mothur.out.log && ## the merged file is named after the input file and keeps its extension, rename it to ## something Galaxy can pick up irrespective of the type of the input mv input.merge.shared merged.dat 2>/dev/null || mv input.merge.list merged.dat 2>/dev/null || mv input.merge.relabund merged.dat
